16→@Service
17→class ProductAssembleService(
18→    private val cachedProxyApplicationService: CachedProxyApplicationService,
19→
20→) {
21→    private val logger by logger()
22→
23→    fun assemble(documents: List<ChangedData<Product>>): List<IndexDocument<ProductDocument>> {
24→        val dependencyId = getDependencyId(documents)
25→        val dependency = cachedProxyApplicationService.fetchDependencies(dependencyId)
26→
27→        return documents
28→            .filter { validateDependency(it, dependency) }
29→            .map {
30→                try {
31→                    when (it.op) {
32→                        Operation.CREATE,
33→                        Operation.UPDATE -> {
34→                            it.toIndexDocument(
35→                                category = dependency.categories[it.afterData?.categoryId]!!,
36→                                mall = dependency.malls[it.afterData?.mallId]!!,
37→                                brandProjection = dependency.brands[it.afterData?.brandId],
38→                                manufacturerProjection = dependency.manufacturers[it.afterData?.manufacturerId],
39→                            )
40→                        }
41→                        Operation.DELETE -> it.toDeleteDocument()
42→                    }
43→                } catch (e: Exception) {
44→                    logger.error(e) { "[Product Assemble] Failed to assemble product document." +
45→                        " productId=[${it.id}], partition=[${it.partition}], offset=[${it.offset}]"}
46→                    throw e
47→                }
48→            }
49→    }
50→
51→    private fun getDependencyId(documents: List<ChangedData<Product>>): DependencyId {
52→        val categoryIds: MutableSet<Int> = mutableSetOf()
53→        val brandIds: MutableSet<Long> = mutableSetOf()
54→        val manufacturerIds: MutableSet<Long> = mutableSetOf()
55→        val mallIds: MutableSet<Int> = mutableSetOf()
56→
57→        documents.forEach {
58→            if (it.shouldFetchCategory) categoryIds.add(it.afterData!!.categoryId)
59→            if (it.shouldFetchBrand) it.afterData?.brandId?.run { brandIds.add(this) }
60→            if (it.shouldFetchManufacturer) it.afterData?.manufacturerId?.run { manufacturerIds.add(this) }
61→            if (it.shouldFetchMall) it.afterData?.mallId?.run { mallIds.add(this) }
62→        }
63→
64→        return DependencyId(
65→            categoryIds = categoryIds,
66→            brandIds = brandIds,
67→            manufacturerIds = manufacturerIds,
68→            mallIds = mallIds,
69→        )
70→    }
71→
72→    private fun validateDependency(document: ChangedData<Product>, dependency: Dependency): Boolean {
73→
74→        if (document.shouldFetchCategory && dependency.categories[document.afterData!!.categoryId] == null) {
75→            logger.warn { "[Product Assemble] Skipped to index product. Category not found. categoryId=[${document.afterData!!.categoryId}]" +
76→                    " productId=[${document.id}], partition=[${document.partition}], offset=[${document.offset}]" }
77→            return false
78→        }
79→
80→        if (document.shouldFetchMall && dependency.malls[document.afterData!!.mallId] == null) {
81→            logger.warn { "[Product Assemble] Skipped to index product. Manufacturer not found. mallId=[${document.afterData!!.mallId}]" +
82→                    " productId=[${document.id}], partition=[${document.partition}], offset=[${document.offset}]" }
83→            return false
84→        }
85→
86→        return true
87→    }
88→}
